const fs = require('fs');
const path = require('path');

function walk(dir, out) {
  let entries;
  try { entries = fs.readdirSync(dir, {withFileTypes:true}); } catch(e) { return; }
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (e.name.endsWith('.md')) out.push(p);
  }
}

const stagingRoot = 'C:/Users/eric_rash/Desktop/DEV/Flint/.claude/worktrees/step1-triage/staging/library';
const vaultRoot = 'C:/Users/eric_rash/Desktop/SecondBrain/Knowledge/library';

let stagingFiles = [];
let vaultFiles = [];
walk(stagingRoot, stagingFiles);
walk(vaultRoot, vaultFiles);

// build slug -> [full paths] map for each
function buildMap(files, root) {
  const map = {};
  for (const f of files) {
    const rel = path.relative(root, f).replace(/\\/g, '/');
    const slug = path.basename(f, '.md');
    if (!map[slug]) map[slug] = [];
    map[slug].push(rel);
  }
  return map;
}

const stagingMap = buildMap(stagingFiles, stagingRoot);
const vaultMap = buildMap(vaultFiles, vaultRoot);

console.log('staging file count:', stagingFiles.length);
console.log('vault file count:', vaultFiles.length);

// Save maps to a temp json for later use
fs.writeFileSync('/tmp/staging_map.json', JSON.stringify(stagingMap));
fs.writeFileSync('/tmp/vault_map.json', JSON.stringify(vaultMap));
fs.writeFileSync('/tmp/staging_root.txt', stagingRoot);
fs.writeFileSync('/tmp/vault_root.txt', vaultRoot);

console.log('sample staging slugs:', Object.keys(stagingMap).slice(0,5));
console.log('sample vault slugs:', Object.keys(vaultMap).slice(0,5));

