// STRICT check: real [[wikilink]] containing the slug (possibly with path prefix before slug, e.g. [[book/slug]] or [[book/slug|text]])
function strictLinked(content, slug) {
  // match [[ ... slug ... ]] where slug appears as the trailing component (after last / if any) up to ]] or |
  const re = new RegExp('\\[\\[[^\\]]*' + slug.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + '[^\\]]*\\]\\]');
  return re.test(content);
}

function checkPairStrict(srcSlug, tgtSlug) {
  const srcR = resolveOne(srcSlug);
  const tgtR = resolveOne(tgtSlug);
  if (srcR.length===0) return {status:'SRC_MISSING'};
  if (tgtR.length===0) return {status:'TGT_MISSING'};
  const results = srcR.map(s => {
    const content = fs.readFileSync(s.full,'utf8');
